import React from 'react';
// @ts-ignore — generated by `npm run build:plugin-manifest-docs` (from docs/site) from
// server/public/model's Manifest struct; gitignored build output, see docs/site/.gitignore.
import rawDocs from '@site/data/plugin-manifest-docs.json';
import styles from './styles.module.css';

type SchemaType = 'array' | 'bool' | 'dict' | 'number' | 'object' | 'string' | 'interface';

type ObjectProperty = {
  Name: string;
  DocHTML?: string;
  Schema?: TypeDocs;
};

type TypeDocs = {
  Type: SchemaType;
  DocHTML?: string;
  ObjectProperties?: ObjectProperty[];
  ValueSchema?: TypeDocs;
};

type ManifestDocs = {
  Schema: TypeDocs;
};

const docs: ManifestDocs | undefined = rawDocs?.Schema ? (rawDocs as ManifestDocs) : undefined;

function titleCase(type: SchemaType): string {
  return type.charAt(0).toUpperCase() + type.slice(1);
}

// Arrays/dicts have no properties of their own — the ToC/Docs walk passes through to their
// element schema, same as the old Hugo `pluginmanifestdocs` shortcode.
function TOC({schema, prefix}: {schema?: TypeDocs; prefix: string}) {
  if (!schema) return null;
  if (schema.Type === 'object') {
    return (
      <ul>
        {(schema.ObjectProperties ?? []).map((prop) => (
          <li key={prop.Name}>
            <a href={`#${prefix}${prop.Name}`}>
              <code>{prop.Name}</code>
            </a>
            {prop.Schema && ` - ${titleCase(prop.Schema.Type)}`}
            {prop.Schema && <TOC schema={prop.Schema} prefix={`${prefix}${prop.Name}.`} />}
          </li>
        ))}
      </ul>
    );
  }
  if (schema.Type === 'array' || schema.Type === 'dict') {
    return <TOC schema={schema.ValueSchema} prefix={prefix} />;
  }
  return null;
}

function Docs({schema, prefix}: {schema?: TypeDocs; prefix: string}) {
  if (!schema) return null;
  if (schema.Type === 'object') {
    return (
      <ul className={styles.docsList}>
        {(schema.ObjectProperties ?? []).map((prop) => (
          <li key={prop.Name} id={`${prefix}${prop.Name}`}>
            <p>
              <code>{prop.Name}</code>
              {prop.Schema && ` - ${titleCase(prop.Schema.Type)}`}
            </p>
            {prop.DocHTML && <div dangerouslySetInnerHTML={{__html: prop.DocHTML}} />}
            {prop.Schema?.DocHTML && <div dangerouslySetInnerHTML={{__html: prop.Schema.DocHTML}} />}
            {prop.Schema && <Docs schema={prop.Schema} prefix={`${prefix}${prop.Name}.`} />}
          </li>
        ))}
      </ul>
    );
  }
  if (schema.Type === 'array' || schema.Type === 'dict') {
    return (
      <>
        {schema.ValueSchema?.DocHTML && <div dangerouslySetInnerHTML={{__html: schema.ValueSchema.DocHTML}} />}
        <Docs schema={schema.ValueSchema} prefix={prefix} />
      </>
    );
  }
  return null;
}

/**
 * Renders the plugin.json/plugin.yaml manifest field reference, generated from
 * `model.Manifest`'s Go doc comments by `gen-plugin-manifest-docs`. Port of the old
 * mattermost-developer-documentation Hugo `pluginmanifestdocs` shortcode.
 */
export default function PluginManifestDocs() {
  if (!docs) {
    return (
      <p>
        Run <code>npm run build:plugin-manifest-docs</code> (from <code>docs/site</code>) to
        generate this documentation.
      </p>
    );
  }

  return (
    <div className={styles.pluginManifestDocs}>
      {docs.Schema.DocHTML && <div dangerouslySetInnerHTML={{__html: docs.Schema.DocHTML}} />}
      <h2>Table of contents</h2>
      <TOC schema={docs.Schema} prefix="" />
      <h2>Documentation</h2>
      <Docs schema={docs.Schema} prefix="" />
    </div>
  );
}
